_recent = defaultdict(lambda: deque(maxlen=24))

def say(event, user_id=None):
    """Return one of 144 event-specific variants without recent repetition."""
    if event not in OPENINGS:
        raise KeyError(event)
    key = (event, user_id)
    recent = _recent[key]
    choices = [a + " " + b for a in OPENINGS[event] for b in ENDINGS[event]]
    available = [v for v in choices if v not in recent]
    result = random.choice(available or choices)
    recent.append(result)
    return result

def variants_count(event):
    return len(OPENINGS[event]) * len(ENDINGS[event])
